  {
    /* Read IT status of JOY_SEL */
    ItStatus = BSP_IO_GetIT(0, JOY_SEL_PIN[JOY1]);
    if (ItStatus > 0)
    {
      BSP_JOY_Callback(JOY1, (uint32_t)JOY_SEL);
      /* Clear IT status of JOY_SEL */
      ItStatus = BSP_IO_ClearIT(0, JOY_SEL_PIN[JOY1]);
