/**
  ******************************************************************************
  * @file    stm32u575i_eval_sd.c
  * @author  MCD Application Team
  * @brief   This file includes the uSD card driver mounted on STM32U575I_EVAL
  *          boards.
  ******************************************************************************
  * @attention
