  * @{
  */
#if (USE_BSP_TS_SX > 0)
static int32_t SX8651_Probe(uint32_t Instance);
#endif /* USE_BSP_TS_MFX */
#if (USE_BSP_TS_MFX > 0)
static int32_t MFX_Probe(uint32_t Instance);
#endif /* USE_BSP_TS_MFX */
static void    TS_EXTI_Callback(void);
